head.script:
/**
 * 최상단(opener, parent 포함) 기준 함수
 */
scwin.isMain = function() {
    return true;
};

/**
 * 전역 변수
 *
 * ============ ============ ==========================
 *  Date         Author       Description
 * ============ ============ ==========================
 * 2022.05.10.   최연구       [NELS]최초생성
 * ============ ============ ==========================
 */
scwin.codeSeper   = '------';  // 코드간 구분자
scwin.sbm_search_target = 'data:json,{"id":"dlt_csDvsCd","key":"data.dlt_csDvsCd"}';
scwin.cortCd = ssgo.getIntgStorage(ssgo.STORAGE.SGM_COND.ID, ssgo.STORAGE.SGM_COND.KIND.cortCd);

/**
 * 화면 pageload 이벤트
 *
 * ============ ============ ==========================
 *  Date         Author       Description
 * ============ ============ ==========================
 * 2022.05.10.   최연구       [NELS]최초생성
 * ============ ============ ==========================
 */    
scwin.onpageload = function() {

    // 사건번호직접입력 숨김
    ibx_fullCsNo.hide();
    //ibx_csSerial.focus();

    // 1. 화면 로드시 기본정보(코드등) 조회 submission
    scwin.sbm_selectCodeInfo();

    // 2. captcha정보 로드
    com.executeSubmission(sbm_captcha);   

    // 4분마다 캡챠문자 갱신
    com.util.setInterval(
        function() {
            btn_reloadCaptcha.trigger("onclick");
        },
        { delay : 1000*60*4, key : "loginTimeout" }
    );

    scwin.setEnterKeyEventOfGrpObj(grp_srchCs, scwin.btn_srchCs_onclick, "input");
};

/**
 * 화면 pageunload 이벤트
 *
 * ============ ============ ==========================
 *  Date         Author       Description
 * ============ ============ ==========================
 * 2022.05.10.   최연구       [NELS]최초생성
 * ============ ============ ==========================
 */
scwin.onpageunload = function() {
};


/**
 *********************************************************************************************************
 * Submission Event Handler
 *********************************************************************************************************
 */
/**
 * SSGO(메모리) 관련 코드조회
 *
 * ============ ============ ==========================
 *  Date         Author       Description
 * ============ ============ ==========================
 * 2022.05.10.   최연구       [NELS]최초생성
 * ============ ============ ==========================
 */
scwin.sbm_selectCodeInfo = function() {
    
    dma_search.set("cortCd", scwin.cortCd);
    dma_search.set("cdScope", "ALL");   // 법원,사건구분 둘다 조회함

    var csNoHistLst = "";
    var dt_csHist = scwin.ufn_getStorageCsHistLst();
    if(!scutilo.isEmpty(dt_csHist)) {
        for(let i = 0; i < dt_csHist.length; i++) {
            csNoHistLst += dt_csHist[i].csYear + dt_csHist[i].csDvsCd + scutilo.getLPadding(dt_csHist[i].csSerial, 7, "0");
            if((i+1) != dt_csHist.length) {
                csNoHistLst += ",";
            }
        }
        dma_search.set("csNoHistLst", csNoHistLst);
    }
    
    com.executeSubmission(sbm_search);
};

/**
 * 코드 조회 submission done 이벤트
 *
 * ============ ============ ==========================
 *  Date         Author       Description
 * ============ ============ ==========================
 * 2022.05.10.   최연구       [NELS]최초생성
 * ============ ============ ==========================
 */
scwin.sbm_search_submitdone = function(e) {
        
    // 화면최로드시에만 법원코드를 셋팅한다.
    if(sbm_search.target !== scwin.sbm_search_target) {
        // 1. 법원코드 셋팅 ---------------------------------
        sbx_cortCd.setEventPause(null, true);   // event lock
        
        dlt_dynamic_cortCd.removeAll();

        // 사건검색 코드관리(메모리) 사용 안할때
        if(ssgo.getProperties("clt.ssgo.memcd.use.yn") == "N") {
            // js법원정보 셋팅
            ssgocbx.setCortCd(sbx_cortCd);
        } else {
            // 메모리 법원정보 셋팅
            dlt_dynamic_cortCd.setJSON(dlt_cortCd.getAllJSON());
        }
        
        sbx_cortCd.setEventPause(null, false);  // event unlock
        
        // 2. 년도코드 셋팅 ---------------------------------
        var csYrdArr = [];
        var ymd      = $p.getCurrentServerDate("yyyyMM");
        var nowYr    = ymd.substring(0,4);
        for(var i = nowYr; i >= 1985; i--) {
            csYrdArr.push({"code" : i, "codeNm" : i});
        }
        csYrdArr.push({"code" : 1969, "codeNm" : 1969});    // 1969년 추가
        
        dlt_csYr.removeAll();
        dlt_csYr.setJSON(csYrdArr);
        sbx_csYr.setValue(ymd.substring(0,4));   // 현재 사건년도 선택      
        
        // 3. 사건구분 셋팅 ----------------------------------
        sbx_csDvsCd.setEventPause(null, true);
        dlt_dynamic_csDvsCd.removeAll();

        // 사건검색 코드관리(메모리) 사용 안할때
        if(ssgo.getProperties("clt.ssgo.memcd.use.yn") == "N") {
            // js사건구분정보 셋팅
            ssgocbx.setCsDvsCd(sbx_csDvsCd, (scutilo.isEmpty(scwin.cortCd))? dlt_dynamic_cortCd.getCellData(0, "code") : scwin.cortCd );
        } else {
            // 메모리 사건구분정보 셋팅
            dlt_dynamic_csDvsCd.setJSON(dlt_csDvsCd.getAllJSON());
        }
        
        sbx_csDvsCd.setEventPause(null, false);
        
        // localStorage에서 검색조건 조회
        scwin.ufn_changeStorageInputStatus('get');     

    } else {
        
        // 사건구분 셋팅 ----------------------------------
        sbx_csDvsCd.setEventPause(null, true);
        dlt_dynamic_csDvsCd.removeAll();
        dlt_dynamic_csDvsCd.setJSON(dlt_csDvsCd.getAllJSON());
        sbx_csDvsCd.setEventPause(null, false);
        
        // 사건번호입력모드 trigger
        if(cbx_chkSanoInputMode.getValue() === "Y") {
            cbx_chkSanoInputMode.trigger("onchange");
        }

        // 사건구분 값 없을때 default 첫번째 elemnet선택
        if(scutilo.isEmpty(sbx_csDvsCd.getValue())){
            sbx_csDvsCd.setSelectedIndex(0);
        }
    }
};    

/**
 * 코드 조회 submission error 이벤트
 *
 * ============ ============ ==========================
 *  Date         Author       Description
 * ============ ============ ==========================
 * 2022.05.10.   최연구       [NELS]최초생성
 * ============ ============ ==========================
 */
scwin.sbm_search_submiterror = function(e) {
    ssgo.printSubmiterror(e);
};

/**
 * 캡챠정보 조회 submission done 이벤트
 *
 * ============ ============ ==========================
 *  Date         Author       Description
 * ============ ============ ==========================
 * 2022.05.10.   최연구       [NELS]최초생성
 * ============ ============ ==========================
 */
scwin.sbm_captcha_submitdone = function(e) {
   
    const captcha = document.querySelector(".form.captcha");
    
    const image = dma_captchaInf.get("image");

    const binary = ssgo.fixBinary(atob(image));
    const blob = new Blob([binary], { type: 'image/png' });

    const url = URL.createObjectURL(blob);     
    
    const img = captcha.querySelector("img");
    img.setAttribute('src', url);
}

/**
 * 캡챠정보 조회 submission error 이벤트
 *
 * ============ ============ ==========================
 *  Date         Author       Description
 * ============ ============ ==========================
 * 2022.05.10.   최연구       [NELS]최초생성
 * ============ ============ ==========================
 */
scwin.sbm_captcha_submiterror = function(e) {
    ssgo.printSubmiterror(e);
};


/**
 *********************************************************************************************************
 * Event Handler
 *********************************************************************************************************
 */
/**
 * 사건번호입력모드 클릭 이벤트
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.06.24.   최연구       [NELS]최초생성
 * ============= ============ ==========================
 */
scwin.cbx_chkSanoInputMode_onchange = function(info) {
    if( cbx_chkSanoInputMode.getValue() === "Y" ) {
        ibx_fullCsNo.setValue("");
        ibx_fullCsNo.show("");
        sbx_csYr.hide();
        sbx_csDvsCd.hide();
        ibx_csSerial.hide();
        ibx_fullCsNo.focus();
    } else {
        ibx_fullCsNo.hide();
        sbx_csYr.show("");
        sbx_csDvsCd.show("");
        ibx_csSerial.show("");
        ibx_csSerial.focus();
    }
};


/**
 * 검색버튼 클릭 이벤트
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.06.24.   최연구       [NELS]최초생성
 * ============= ============ ==========================
 */
scwin.btn_srchCs_onclick = function(e) {
    // 각급법원 parameter
    var param   = com.data.getParameter() || ssgo.getParameter();
    
    // 정합성 체크
    if(!scwin.vfn_validateCsSrch(param)) {
        return false;
    }

	var paramData = {
        cortId        : param.cortId, 
        cortCd        : sbx_cortCd.getValue(),      // 법원코드
        cortNm        : sbx_cortCd.getText(),       // 법원명
        csYear        : sbx_csYr.getValue(),        // 사건년도
        csDvsCd       : sbx_csDvsCd.getValue(),     // 사건구분
        csDvsNm       : sbx_csDvsCd.getText(),      // 사건구분명
        csSerial      : ibx_csSerial.getValue(),    // 사건시리얼번호
	    btprtNm       : ibx_btprNm.getValue(),      // 당사자명
        fullCsNo      : ibx_fullCsNo.getValue(),    // 사건번호(FULL)        
	    captchaAnswer : ibx_answer.getValue(),      // 캡챠번호
        encCaptchaAnswer : dma_captchaInf.get("answer"),   // 캡챠번호
        comTaskTypCd : dlt_dynamic_csDvsCd.getCellData(sbx_csDvsCd.getSelectedIndex(), "comTaskTypCd"), // 재판사무업무유형코드 
        chkSanoInputMode : cbx_chkSanoInputMode.getValue(),
	};
    
    //사건검색을 호출한 각급법원의 result 페이지로 submit한다
    var cortUrl = "https://" + param.cortId + ".scourt.go.kr/common/util/safind_result.jsp";
    ssgo.sendPostForm(cortUrl, paramData, "_parent");   

    //todo : 각급법원 테스트 필요함. 임시용
    //paramData.callDomain = "cortKindDomain"
    //window.open("" ,"csSrchDetail", "toolbar=no, width=1100, height=800, directories=no, status=no, scrollorbars=no, resizable=no"); 
    //ssgo.sendPostForm(ssgo.getCtxtPathUrl("/srchCsDetail.on"), paramData, "csSrchDetail"); 

};


/**
 * 자동입력방지(캡챠) 이미지 리로딩
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.06.24.   최연구       [NELS]최초생성
 * ============= ============ ==========================
 */
scwin.btn_reloadCaptcha_onclick = function(e) {
    com.executeSubmission(sbm_captcha);
};


/**
 * 캡챠 음성듣기
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.06.24.   최연구       [NELS]최초생성
 * ============= ============ ==========================
 */
scwin.btn_voiceListen_onclick = function(e) {
    if(!scutilo.isEmpty(dma_captchaInf) && dma_captchaInf.get("audio")){
        const binary = ssgo.fixBinary(atob(dma_captchaInf.get("audio")));
        const blob = new Blob([binary], { type: 'audio/wave' });
        const url = URL.createObjectURL(blob);
        new Audio(url).play();
    }  
};


/**
 * 법원코드 onchange 이벤트
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.06.24.   최연구       [NELS]최초생성
 * ============= ============ ==========================
 */
scwin.sbx_cortCd_onchange = function(info) {
    // 사건검색 코드관리(메모리) 사용 안할때
    if(ssgo.getProperties("clt.ssgo.memcd.use.yn") == "N") {
        
        // js사건구분정보 셋팅
        dlt_dynamic_csDvsCd.removeAll();
        ssgocbx.setCsDvsCd(sbx_csDvsCd, sbx_cortCd.getValue());
        
        // 사건번호입력모드 trigger
        if(cbx_chkSanoInputMode.getValue() === "Y") {
            cbx_chkSanoInputMode.trigger("onchange");
        }

        // 사건구분 값 없을때 default 첫번째 elemnet선택
        if(scutilo.isEmpty(sbx_csDvsCd.getValue())){
            sbx_csDvsCd.setSelectedIndex(0);
        }

    } else {
        dma_search.set("cortCd", sbx_cortCd.getValue());

        sbm_search.target = scwin.sbm_search_target;
        com.executeSubmission(sbm_search);

    }
};

/**
 *********************************************************************************************************
 * Validate 
 *********************************************************************************************************
 */
/**
 * 사건검색 검색조건 정합성 체크
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.06.24.   최연구       [NELS]최초생성
 * ============= ============ ==========================
 */
scwin.vfn_validateCsSrch = function(param) {

    // 각급 법원 도메인Id체크
    if(scutilo.isEmpty(param.cortId)) {
        alert(scutilo.getMsg(ssgomsg.SSGO.W_0103));    //W_0103: "법원 홈페이지를 찾을 수 없습니다."
        return false;
    }

    // 사건번호 입력모드 정합성체크
    if(cbx_chkSanoInputMode.getValue() === "Y" && !scwin.ufn_textToSbxCsNo()) return false;
    
    var csSerial  = ibx_csSerial.getValue();
    var btprNm    = ibx_btprNm.getValue();
    var answer    = ibx_answer.getValue();

    if( sbx_cortCd.getValue().indexOf("A") === 0 ) {
        alert(scutilo.getMsg(ssgomsg.SSGO.I_0002, "법원을")); //I_0002: "법원을 선택하십시오."
        sbx_cortCd.focus();
        return false;
    }

    if( sbx_csDvsCd.getValue().indexOf("A") === 0 ) {
        alert(scutilo.getMsg(ssgomsg.SSGO.I_0002, "사건구분을")); //I_0002: "사건구분을 선택하십시오."
        sbx_csDvsCd.focus();
        return false;        
    }

    csSerial = csSerial.replace(/^\s*|\s*$/g, '');
    ibx_csSerial.setValue(csSerial);

    if(scutilo.isEmpty(csSerial)) {
        alert(scutilo.getMsg(ssgomsg.SSGO.I_0001, "사건일련번호를")); //I_0001: "사건일련번호를 입력하십시오."
        ibx_csSerial.focus();
        return false;        
    }

    // [사건검색]홈페이지 사건검색 금칙어 처리
    btprNm = btprNm.replace(/\s/g, '');
    if(btprNm === "당사자명필수입력" || btprNm.length < 2 ) {
        alert(scutilo.getMsg(ssgomsg.SSGO.I_0002, "당사자명을 2자이상")); //I_0001: "당사자명을 2자이상을 입력하십시오."
        ibx_btprNm.focus();
        return false;        
    }
    ibx_btprNm.setValue(btprNm);


    var  anum=/(^\d+$)|(^\d+\.\d+$)/  

    if(!anum.test(csSerial)) {
        alert(scutilo.getMsg(ssgomsg.SSGO.I_0003, "사건일련번호는")); //I_0003: "사건일련번호는 숫자만 입력하십시오"
        ibx_csSerial.setValue("");
        ibx_csSerial.focus();
        return false;        
    }

    var filter_word = /[$\\\\#\%\^\&\*\+\_\`\~\=\|\,\'\"\-\:\;\％\/]/;  //특수문자를 배열
    if (btprNm.search(filter_word)>=0) {
        alert(scutilo.getMsg(ssgomsg.SSGO.I_0004, "당사자명에")); //I_0004: "당사자명에 특수문자는 사용할 수 없습니다."
        ibx_btprNm.setValue("");
        ibx_btprNm.focus();
        return false;
    }

    // 대법원 홈페이지 사건검색에서 금칙어를 사용 할 수 없도록 처리
    var psBanWordList = ssgo.getProperties("clt.ssgo.ban.word.list");
    var lines = psBanWordList.split(",");

    // 홈페이지 사건검색 금칙어 처리
    if( psBanWordList.indexOf(btprNm)>=0 ) {
        // 금칙어 추가 및 메세지 처리
        alert(scutilo.getMsg(ssgomsg.SSGO.I_0005, btprNm, btprNm)); //I_0005 : "[btprNm]만 입력하는 경우 검색이 제한됩니다.\n" + "당사자명 전부를 입력하거나, [btprNm] 이외의 부분을 추가로 입력하시기 바랍니다.\n" + "당사자명이 2자인 경우, 사건상대방의 이름을 입력하여 조회하시기 바랍니다."
        ibx_btprNm.focus();
        return false; 
    }

    answer = answer.replace(/\s/g, '');
    if ( answer.length != 6 ) {
        alert(scutilo.getMsg(ssgomsg.SSGO.I_0001, "자동입력 방지 문자 6자를"));
        ibx_answer.focus();
        return false;        
    }    
    
    // 캡챠암호화 문자체크
    var encAnswer = dma_captchaInf.get("answer");
    if(scutilo.isEmpty(encAnswer)) {
        alert(scutilo.getMsg(ssgomsg.SSGO.E_0007, "캡챠 랜더링"));    //I_0001: "캡챠 랜더링 처리 중 오류가 발생하였습니다."
        return false;
    }

    return true;
}


/**
 *********************************************************************************************************
 * User Function
 *********************************************************************************************************
 */

/**
 * 사건번호(입력모드) 검증 
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.06.24.   최연구       [NELS]최초생성
 * ============= ============ ==========================
 */
scwin.ufn_textToSbxCsNo = function() {
    var pos = 0;
    var year = "";
    var csDvs = "";
    var saSerial = "";
    var tmpStr = ""
    var iscsDvsCd = false;
    var saNo = ibx_fullCsNo.getValue();

    if(scutilo.isEmpty(saNo)) {
        alert(scutilo.getMsg(ssgomsg.SSGO.I_0001, "사건번호를")); //I_0001: "사건번호를 입력하십시오.",
        ibx_fullCsNo.focus();
        return false;        
    }

    saNo = saNo.replace(/\s/g, '');

    for (let i=0;i< saNo.length ; i++ ) {
        if (saNo.charAt(i) < "0" || saNo.charAt(i) > "9") {
            pos = i;
            break;
        }
    }

    // 년도체크
    year  = scwin.ufn_getYear(saNo.substr(0, pos));
    if (year.length !== 4) {
        alert(scutilo.getMsg(ssgomsg.SSGO.I_0006, "년도를"));    //I_0006 : "올바른 년도를 입력하세요."
        return false;
    }
    sbx_csYr.setValue(year);
    
    // 사건구분 체크
    tmpStr = saNo.substr(pos,saNo.length);
    for (let i=0;i< tmpStr.length ; i++ ) {
        if (tmpStr.charAt(i) >= "0" && tmpStr.charAt(i) <= "9") {
            pos = i;
            break;
        }
    }
    csDvs = tmpStr.substr(0,pos);
    
    for(let i = 0; i < dlt_dynamic_csDvsCd.getRowCount(); i++) {
       if(csDvs === dlt_dynamic_csDvsCd.getCellData(i, dlt_dynamic_csDvsCd.cellIdList[1])) {
           sbx_csDvsCd.setSelectedIndex(i);
           iscsDvsCd = true;
           break;
       }
    }

    if( !iscsDvsCd ) {
        alert(scutilo.getMsg(ssgomsg.SSGO.I_0006, "사건구분을"));    //I_0006 : "올바른 사건구분을 입력하세요."
        return false;
    }

    // 사건일련번호 체크
    saSerial = tmpStr.substr(pos, tmpStr.length);
    if (scutilo.isEmpty(saSerial) || saSerial.length > 7) {
        alert(scutilo.getMsg(ssgomsg.SSGO.I_0006, "사건번호를"));    //I_0006 : "올바른 사건번호를 입력하세요."
        return false;
    }
    ibx_csSerial.setValue(saSerial);

    return true;    
}

/**
 * 년도 조회
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.06.24.   최연구       [NELS]최초생성
 * ============= ============ ==========================
 */
scwin.ufn_getYear = function(year) {
    var iYear = 0;
    year = year.replace(/\s/g, '');

    if (year.length !== 2 && year.length !== 4) {
        return "";
    }

    for (let i=0; i< year.length ; i++ ) {
        if ( year.charAt(i) < "0" || year.charAt(i) > "9" ) {
            return "";
        }
    }
    iYear = parseInt(year, 10);

    if (year.length === 2) {
        if(iYear >= 50) {
            iYear = iYear + 1900;
        } else {
            iYear = iYear + 2000;
        }
    }

    var ymd    = $p.getCurrentServerDate("yyyyMM");
    var nowYr  = ymd.substring(0,4);
    
    if(iYear > nowYr) {
        return "";
    } else {
        return iYear.toString();
    }
}

/**
 * 로컬스토리지에 화면의 검색조건(필터)의 값(상태)를 조회 및 저장
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.06.24.   최연구       [NELS]최초생성
 * ============= ============ ==========================
 */
scwin.ufn_changeStorageInputStatus = function(type) {
    var storage  = ssgo.STORAGE;
    var condId   = storage.SGM_COND.ID;
    var condKind = storage.SGM_COND.KIND;
    
    if(type === "get") {
        // 법원
        if(!scutilo.isEmpty(com.storage.get(condId, condKind.cortCd))) {
            sbx_cortCd.setEventPause(null, true);
            sbx_cortCd.setValue(ssgo.decode(com.storage.get(condId, condKind.cortCd)));
            sbx_cortCd.setEventPause(null, false);
        } else {
            sbx_cortCd.setValue("000100");
        }
        // 년도
        if(!scutilo.isEmpty(com.storage.get(condId, condKind.csYr))) {
            sbx_csYr.setValue(ssgo.decode(com.storage.get(condId, condKind.csYr)));
        }
        // 사건구분
        if(!scutilo.isEmpty(com.storage.get(condId, condKind.csDvsCd))) {
            sbx_csDvsCd.setValue(ssgo.decode(com.storage.get(condId, condKind.csDvsCd)));
        }
    }
}

/**
 * 로컬스토리지의 사건검색 이력조회
 *
 * ============= ============ ==========================
 *  Date          Author       Description
 * ============= ============ ==========================
 *  2022.06.24.   최연구       [NELS]최초생성
 * ============= ============ ==========================
 */
scwin.ufn_getStorageCsHistLst = function() {

    var storage  = ssgo.STORAGE;
    var condId   = storage.SGM_COND.ID;
    var condKind = storage.SGM_COND.KIND;
    
    var jsonCsHist = ssgo.decode(com.storage.get(storage.SGM_HIST.ID, storage.SGM_HIST.KIND.mainCsHist));
    var dt_csHist = scutilo.isEmpty(jsonCsHist) ? "" : JSON.parse(jsonCsHist);

    return dt_csHist;
}

/**
 * 해당 그룹 안의 컴포넌트에서 엔터키가 발생하면 해당 컴포넌트의 objFunc 함수를 실행한다.
 *
 * @param {Object} grpObj 그룹 객체
 * @param {Object} objFunc 함수 객체
 * @param {String} includePlugin 바인드하는 객체타입
 * @example
    scwin.setEnterKeyEvent(grp_sample, scwin.search, "input textarea");
 * ============ ============ ==========================
 *  Date         Author       Description
 * ============ ============ ==========================
 * 2023.11.01.   최연구       [NELS]최초생성
 * ============ ============ ==========================
 */
scwin.setEnterKeyEventOfGrpObj = function (grpObj, objFunc, includePlugin) {
    var objArr = com.util.getChildren(grpObj, {
        //includePlugin: "checkbox checkcombobox editor input inputCalendar multiselect radio selectbox searchbox secret textarea autoComplete",
        includePlugin: includePlugin,
        recursive: true
    });

    try {
        for (let i = 0; i < objArr.length; i++) {
            try {
                if (typeof objFunc === "function") {
                    objArr[i].bind("onkeyup", function (e) {
                        if (e.keyCode === 13) {
                            if (typeof this.getRef === "function") {
                                objFunc();
                            }
                        }
                    });
                }
            } catch (e) {
                console.error("[setEnterKeyEvent] Exception :: " + e.message);
            } finally {
                dataCollection = null;
            }
        }
    } catch (ex) {
        console.error(ex);
    } finally {
        objArr = null;
    }
};
